define({"topics":[{"title":"Doing the local TR coil Stability test","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">This tool measures and shows the magnitude drift, phase offset, and echo shift using Fast Spin Echo and Gradient Resolved Echo sequences for either the body coil or local coils.<\/span> Local TR coil scans are disabled until this task is completed.<\/p>","href":"t_DoingTheLocalTRCoil_StabilityTestSPT.html","attributes":{"data-id":"id_2001631"},"menu":{"hasChildren":false},"tocID":"id_2001631-d46e136250","topics":[]},{"title":"ACR accreditation scan troubleshooting","shortdesc":"<p class=\"shortdesc\">ACR accreditation scan troubleshooting.<\/p>","href":"r_ts_ACR-Accreditation-Scan-Troubleshooting_16016407.html","attributes":{"data-id":"id_12374102"},"menu":{"hasChildren":false},"tocID":"id_12374102-d46e136356","topics":[]}]});